package br.com.gamelocadora.dao;
import br.com.gamelocadora.config.Conexao;import br.com.gamelocadora.exception.RegraNegocioException;import br.com.gamelocadora.model.*;
import java.sql.*;import java.math.*;import java.time.*;import java.util.*;
public class JdbcLocadoraDAO implements LocadoraDAO {
 private List<String> linhas(String sql)throws SQLException{List<String> out=new ArrayList<>();try(Connection c=Conexao.obter();PreparedStatement p=c.prepareStatement(sql);ResultSet r=p.executeQuery()){ResultSetMetaData m=r.getMetaData();while(r.next()){StringJoiner s=new StringJoiner(" | ");for(int i=1;i<=m.getColumnCount();i++)s.add(String.valueOf(r.getObject(i)));out.add(s.toString());}}return out;}
 public long inserirCliente(Cliente x)throws SQLException{return inserir("INSERT INTO cliente(cliente_nome,cliente_email,cliente_telefone) VALUES(?,?,?) RETURNING cliente_id",p->{p.setString(1,x.getClienteNome());p.setString(2,x.getClienteEmail());p.setString(3,x.getClienteTelefone());});}
 public void atualizarCliente(long id,Cliente x)throws SQLException{exec("UPDATE cliente SET cliente_nome=?,cliente_email=?,cliente_telefone=?,cliente_ativo=? WHERE cliente_id=?",p->{p.setString(1,x.getClienteNome());p.setString(2,x.getClienteEmail());p.setString(3,x.getClienteTelefone());p.setBoolean(4,x.isClienteAtivo());p.setLong(5,id);});}
 public void excluirCliente(long id)throws SQLException{exec("UPDATE cliente SET cliente_ativo=FALSE WHERE cliente_id=?",p->p.setLong(1,id));}
 public List<String> listarClientes()throws SQLException{return linhas("SELECT cliente_id,cliente_nome,cliente_email,cliente_telefone,cliente_ativo FROM cliente ORDER BY cliente_id");}
 public long inserirJogo(Midia x)throws SQLException{return inserir("INSERT INTO jogo(jogo_titulo,jogo_plataforma,jogo_genero,jogo_formato,jogo_valor_diaria) VALUES(?,?,?,?,?) RETURNING jogo_id",p->{p.setString(1,x.getJogoTitulo());p.setString(2,x.getJogoPlataforma());p.setString(3,x.getJogoGenero());p.setString(4,x instanceof JogoDisco?"DISCO":"CARTUCHO");p.setBigDecimal(5,x.getJogoValorDiaria());});}
 public void atualizarJogo(long id,Midia x)throws SQLException{exec("UPDATE jogo SET jogo_titulo=?,jogo_plataforma=?,jogo_genero=?,jogo_formato=?,jogo_valor_diaria=?,jogo_ativo=? WHERE jogo_id=?",p->{p.setString(1,x.getJogoTitulo());p.setString(2,x.getJogoPlataforma());p.setString(3,x.getJogoGenero());p.setString(4,x instanceof JogoDisco?"DISCO":"CARTUCHO");p.setBigDecimal(5,x.getJogoValorDiaria());p.setBoolean(6,x.isJogoAtivo());p.setLong(7,id);});}
 public void excluirJogo(long id)throws SQLException{exec("UPDATE jogo SET jogo_ativo=FALSE WHERE jogo_id=?",p->p.setLong(1,id));}
 public List<String> listarJogos()throws SQLException{return linhas("SELECT jogo_id,jogo_titulo,jogo_plataforma,jogo_genero,jogo_formato,jogo_valor_diaria,jogo_ativo FROM jogo ORDER BY jogo_id");}
 public long inserirExemplar(long j,String cod,String est,String obs)throws SQLException{return inserir("INSERT INTO exemplar(exemplar_jogo_id,exemplar_codigo,exemplar_estado,exemplar_observacao) VALUES(?,?,?,?) RETURNING exemplar_id",p->{p.setLong(1,j);p.setString(2,cod);p.setString(3,est);p.setString(4,obs);});}
 public void atualizarExemplar(long id,long j,String cod,String est,String obs,boolean ativo)throws SQLException{exec("UPDATE exemplar SET exemplar_jogo_id=?,exemplar_codigo=?,exemplar_estado=?,exemplar_observacao=?,exemplar_ativo=? WHERE exemplar_id=?",p->{p.setLong(1,j);p.setString(2,cod);p.setString(3,est);p.setString(4,obs);p.setBoolean(5,ativo);p.setLong(6,id);});}
 public void excluirExemplar(long id)throws SQLException{exec("UPDATE exemplar SET exemplar_ativo=FALSE WHERE exemplar_id=?",p->p.setLong(1,id));}
 public List<String> listarExemplares()throws SQLException{return linhas("SELECT e.exemplar_id,e.exemplar_codigo,j.jogo_titulo,e.exemplar_estado,e.exemplar_observacao,e.exemplar_ativo FROM exemplar e JOIN jogo j ON j.jogo_id=e.exemplar_jogo_id ORDER BY e.exemplar_id");}
 public List<String> listarDisponiveis()throws SQLException{return linhas("SELECT e.exemplar_id,e.exemplar_codigo,j.jogo_titulo,j.jogo_plataforma,j.jogo_valor_diaria FROM exemplar e JOIN jogo j ON j.jogo_id=e.exemplar_jogo_id WHERE e.exemplar_ativo AND j.jogo_ativo AND NOT EXISTS(SELECT 1 FROM aluguel a WHERE a.aluguel_exemplar_id=e.exemplar_id AND a.aluguel_data_devolucao_real IS NULL) ORDER BY j.jogo_titulo");}
 public long inserirAluguel(long cliente,long exemplar,LocalDate retirada)throws SQLException{
  try(Connection c=Conexao.obter()){c.setAutoCommit(false);try{
   try(PreparedStatement p=c.prepareStatement("SELECT c.cliente_id,e.exemplar_id,j.jogo_valor_diaria FROM cliente c CROSS JOIN exemplar e JOIN jogo j ON j.jogo_id=e.exemplar_jogo_id WHERE c.cliente_id=? AND c.cliente_ativo AND e.exemplar_id=? AND e.exemplar_ativo AND j.jogo_ativo FOR UPDATE OF e")){p.setLong(1,cliente);p.setLong(2,exemplar);try(ResultSet r=p.executeQuery()){if(!r.next())throw new RegraNegocioException("Cliente, jogo ou exemplar inexistente/inativo.");BigDecimal total=r.getBigDecimal(3).multiply(BigDecimal.valueOf(7));try(PreparedStatement q=c.prepareStatement("INSERT INTO aluguel(aluguel_cliente_id,aluguel_exemplar_id,aluguel_data_retirada,aluguel_data_prevista_devolucao,aluguel_valor_total) VALUES(?,?,?,?,?) RETURNING aluguel_id")){q.setLong(1,cliente);q.setLong(2,exemplar);q.setDate(3,java.sql.Date.valueOf(retirada));q.setDate(4,java.sql.Date.valueOf(retirada.plusDays(7)));q.setBigDecimal(5,total);try(ResultSet z=q.executeQuery()){z.next();long id=z.getLong(1);c.commit();return id;}}}}
  }catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;if(e instanceof RuntimeException x)throw x;throw new SQLException(e);}}
 }
 public void atualizarObservacaoAluguel(long id,String obs)throws SQLException{exec("UPDATE aluguel SET aluguel_observacao=? WHERE aluguel_id=? AND aluguel_data_devolucao_real IS NULL",p->{p.setString(1,obs);p.setLong(2,id);});}
 public void excluirAluguel(long id)throws SQLException{exec("DELETE FROM aluguel WHERE aluguel_id=?",p->p.setLong(1,id));}
 public BigDecimal devolver(long id,LocalDate data)throws SQLException{try(Connection c=Conexao.obter()){c.setAutoCommit(false);try{LocalDate prevista;BigDecimal total;try(PreparedStatement p=c.prepareStatement("SELECT aluguel_data_prevista_devolucao,aluguel_valor_total FROM aluguel WHERE aluguel_id=? AND aluguel_data_devolucao_real IS NULL FOR UPDATE")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new RegraNegocioException("Aluguel inexistente ou já devolvido.");prevista=r.getDate(1).toLocalDate();total=r.getBigDecimal(2);}}LocalDate limite=prevista.getDayOfWeek()==DayOfWeek.SUNDAY?prevista.plusDays(1):prevista;long atraso=Math.max(0,java.time.temporal.ChronoUnit.DAYS.between(limite,data));BigDecimal multa=total.multiply(new BigDecimal("0.02")).multiply(BigDecimal.valueOf(atraso)).setScale(2,RoundingMode.HALF_UP);try(PreparedStatement p=c.prepareStatement("UPDATE aluguel SET aluguel_data_devolucao_real=?,aluguel_valor_multa=? WHERE aluguel_id=?")){p.setDate(1,java.sql.Date.valueOf(data));p.setBigDecimal(2,multa);p.setLong(3,id);p.executeUpdate();}c.commit();return multa;}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;if(e instanceof RuntimeException x)throw x;throw new SQLException(e);}}}
 public List<String> listarAlugueis()throws SQLException{return linhas("SELECT aluguel_id,aluguel_cliente_id,aluguel_exemplar_id,aluguel_data_retirada,aluguel_data_prevista_devolucao,aluguel_data_devolucao_real,aluguel_valor_total,aluguel_valor_multa FROM aluguel ORDER BY aluguel_id DESC");}
 public List<String> listarAbertos()throws SQLException{return linhas("SELECT aluguel_id,aluguel_cliente_id,aluguel_exemplar_id,aluguel_data_prevista_devolucao,aluguel_valor_total FROM aluguel WHERE aluguel_data_devolucao_real IS NULL ORDER BY aluguel_data_prevista_devolucao");}
 public List<String> listarAtrasados(LocalDate hoje)throws SQLException{List<String> out=new ArrayList<>();String sql="SELECT aluguel_id,aluguel_cliente_id,aluguel_exemplar_id,aluguel_data_prevista_devolucao FROM aluguel WHERE aluguel_data_devolucao_real IS NULL AND (CASE WHEN EXTRACT(ISODOW FROM aluguel_data_prevista_devolucao)=7 THEN aluguel_data_prevista_devolucao + 1 ELSE aluguel_data_prevista_devolucao END) < ? ORDER BY aluguel_data_prevista_devolucao";try(Connection c=Conexao.obter();PreparedStatement p=c.prepareStatement(sql)){p.setDate(1,java.sql.Date.valueOf(hoje));try(ResultSet r=p.executeQuery()){while(r.next())out.add(r.getLong(1)+" | "+r.getLong(2)+" | "+r.getLong(3)+" | "+r.getDate(4));}}return out;}
 public List<String> consultaJoin()throws SQLException{return linhas("SELECT a.aluguel_id,c.cliente_nome,j.jogo_titulo,j.jogo_plataforma,e.exemplar_codigo,a.aluguel_data_retirada,a.aluguel_data_prevista_devolucao,a.aluguel_data_devolucao_real,a.aluguel_valor_multa FROM aluguel a JOIN cliente c ON c.cliente_id=a.aluguel_cliente_id JOIN exemplar e ON e.exemplar_id=a.aluguel_exemplar_id JOIN jogo j ON j.jogo_id=e.exemplar_jogo_id ORDER BY a.aluguel_id DESC");}
 public long inserirJogoComExemplar(Midia j,String cod,String estado,String obs)throws SQLException{try(Connection c=Conexao.obter()){c.setAutoCommit(false);try{long jid;try(PreparedStatement p=c.prepareStatement("INSERT INTO jogo(jogo_titulo,jogo_plataforma,jogo_genero,jogo_formato,jogo_valor_diaria) VALUES(?,?,?,?,?) RETURNING jogo_id")){p.setString(1,j.getJogoTitulo());p.setString(2,j.getJogoPlataforma());p.setString(3,j.getJogoGenero());p.setString(4,j instanceof JogoDisco?"DISCO":"CARTUCHO");p.setBigDecimal(5,j.getJogoValorDiaria());try(ResultSet r=p.executeQuery()){r.next();jid=r.getLong(1);}}try(PreparedStatement p=c.prepareStatement("INSERT INTO exemplar(exemplar_jogo_id,exemplar_codigo,exemplar_estado,exemplar_observacao) VALUES(?,?,?,?)")){p.setLong(1,jid);p.setString(2,cod);p.setString(3,estado);p.setString(4,obs);p.executeUpdate();}c.commit();return jid;}catch(Exception e){c.rollback();if(e instanceof SQLException s)throw s;if(e instanceof RuntimeException x)throw x;throw new SQLException(e);}}}
 @FunctionalInterface private interface Binder{void bind(PreparedStatement p)throws SQLException;}
 private long inserir(String sql,Binder b)throws SQLException{try(Connection c=Conexao.obter();PreparedStatement p=c.prepareStatement(sql)){b.bind(p);try(ResultSet r=p.executeQuery()){r.next();return r.getLong(1);}}}
 private void exec(String sql,Binder b)throws SQLException{try(Connection c=Conexao.obter();PreparedStatement p=c.prepareStatement(sql)){b.bind(p);if(p.executeUpdate()==0)throw new RegraNegocioException("Registro não encontrado.");}}
}
